#!/usr/bin/env Rscript

# Prepare manuscript-ready tables and figures comparing the predictive
# performance of GAM-DMR (MGCV), SOMNiBUS, DMRcate, and BSmooth across the
# same 100 repeated family-aware outer train/test splits.
#
# Required inputs are the collected outputs generated by the four primary
# prediction pipelines under results/15_revision/5_cv/5_prediction/.
#
# Main outputs:
#   - descriptive performance table across outer test splits;
#   - corrected repeated-CV pairwise comparisons;
#   - each regional method versus the covariate-only model;
#   - model-complexity and feature-selection summaries;
#   - subject-averaged ROC, PR, and calibration curves;
#   - manuscript-ready PDF and PNG figures;
#   - a text summary that can be adapted for the Results section.

suppressPackageStartupMessages({
  library(data.table)
  library(ggplot2)
  library(pROC)
  library(PRROC)
})

data.table::setDTthreads(1L)
options(stringsAsFactors = FALSE)

# ------------------------------- configuration -------------------------------

PATH_wk <- path.expand(
  Sys.getenv("PATH_WK", "~/scratch/UQAC/meth/")
)

prediction_root <- file.path(
  PATH_wk,
  "results/15_revision/5_cv/5_prediction"
)

method_config <- data.table(
  method_key = c("MGCV", "SOMNiBUS", "DMRcate", "BSmooth"),
  method_display = c("GAM-DMR", "SOMNiBUS", "DMRcate", "BSmooth"),
  method_order = 1:4,
  primary_model = c(
    "MGCV_PC12_LASSO",
    "SOMNiBUS_PC12_LASSO",
    "DMRcate_PC12_LASSO",
    "BSmooth_PC12_LASSO"
  ),
  input_root = c(
    Sys.getenv(
      "MGCV_PREDICTION_OUTPUT",
      file.path(prediction_root, "1_mgcv_primary")
    ),
    Sys.getenv(
      "SOMNIBUS_PREDICTION_OUTPUT",
      file.path(prediction_root, "2_somnibus_primary")
    ),
    Sys.getenv(
      "DMRCATE_PREDICTION_OUTPUT",
      file.path(prediction_root, "3_dmrcate_primary")
    ),
    Sys.getenv(
      "BSMOOTH_PREDICTION_OUTPUT",
      file.path(prediction_root, "4_bsmooth_primary")
    )
  ),
  file_prefix = c("mgcv", "somnibus", "dmrcate", "bsmooth")
)

output_root <- path.expand(
  Sys.getenv(
    "REGIONAL_COMPARISON_OUTPUT",
    file.path(prediction_root, "5_regional_method_comparison")
  )
)

table_dir <- file.path(output_root, "tables")
figure_dir <- file.path(output_root, "figures")
data_dir <- file.path(output_root, "data")
qc_dir <- file.path(output_root, "qc")

expected_splits <- suppressWarnings(
  as.integer(Sys.getenv("EXPECTED_SPLITS", "100"))
)

overwrite <- Sys.getenv("OVERWRITE", "0") %in%
  c("1", "TRUE", "true", "T", "yes", "YES")

n_calibration_bins <- suppressWarnings(
  as.integer(Sys.getenv("N_CALIBRATION_BINS", "10"))
)

top_regions_per_method <- suppressWarnings(
  as.integer(Sys.getenv("TOP_REGIONS_PER_METHOD", "12"))
)

if (is.na(expected_splits) || expected_splits < 2L) {
  stop("EXPECTED_SPLITS must be at least 2.")
}

if (is.na(n_calibration_bins) || n_calibration_bins < 3L) {
  stop("N_CALIBRATION_BINS must be at least 3.")
}

if (is.na(top_regions_per_method) || top_regions_per_method < 1L) {
  stop("TOP_REGIONS_PER_METHOD must be positive.")
}

if (dir.exists(output_root)) {
  old_files <- list.files(output_root, recursive = TRUE, full.names = TRUE)

  if (length(old_files) > 0L && !overwrite) {
    stop(
      "Comparison output already exists. Set OVERWRITE=1 to replace it. ",
      "First existing file: ", old_files[1L]
    )
  }

  if (overwrite) {
    unlink(output_root, recursive = TRUE, force = TRUE)
  }
}

for (d in c(output_root, table_dir, figure_dir, data_dir, qc_dir)) {
  dir.create(d, recursive = TRUE, showWarnings = FALSE)
}

