# -------------------------------- utilities ----------------------------------

repair_duplicate_column_names <- function(dt, file_path, label) {
  nm <- names(dt)

  if (!anyDuplicated(nm)) {
    return(dt)
  }

  # Compatibility with the first MGCV/SOMNiBUS output version, which could
  # contain both total test n and evaluable test n under the same name.
  n_test_idx <- which(nm == "n_test")

  if (length(n_test_idx) > 1L) {
    nm[n_test_idx[-1L]] <- paste0(
      "n_evaluable_test",
      if (length(n_test_idx) > 2L) {
        paste0("_", seq_len(length(n_test_idx) - 1L))
      } else {
        ""
      }
    )
  }

  if (anyDuplicated(nm)) {
    duplicate_names <- unique(
      nm[duplicated(nm) | duplicated(nm, fromLast = TRUE)]
    )

    stop(
      label,
      " still has duplicated column names after repair: ",
      basename(file_path),
      " [",
      paste(duplicate_names, collapse = ", "),
      "]"
    )
  }

  setnames(dt, nm)
  dt
}

read_required_table <- function(file_path, label) {
  if (!file.exists(file_path)) {
    stop(label, " does not exist: ", file_path)
  }

  dt <- fread(file_path, showProgress = FALSE)
  repair_duplicate_column_names(dt, file_path, label)
}

require_columns <- function(dt, columns, label) {
  missing_columns <- setdiff(columns, names(dt))

  if (length(missing_columns) > 0L) {
    stop(
      label,
      " is missing columns: ",
      paste(missing_columns, collapse = ", ")
    )
  }
}

as_logical_safe <- function(x) {
  if (is.logical(x)) return(x)

  as.character(x) %in% c(
    "1", "TRUE", "true", "T", "yes", "YES"
  )
}

safe_mean <- function(x) {
  x <- as.numeric(x)
  x <- x[is.finite(x)]
  if (length(x) == 0L) NA_real_ else mean(x)
}

safe_sd <- function(x) {
  x <- as.numeric(x)
  x <- x[is.finite(x)]
  if (length(x) < 2L) NA_real_ else stats::sd(x)
}

safe_quantile <- function(x, p) {
  x <- as.numeric(x)
  x <- x[is.finite(x)]
  if (length(x) == 0L) NA_real_ else as.numeric(
    stats::quantile(x, p, names = FALSE, type = 7)
  )
}

safe_roc_auc <- function(y, p) {
  y <- as.integer(y)
  p <- as.numeric(p)
  keep <- is.finite(y) & is.finite(p)
  y <- y[keep]
  p <- p[keep]

  if (length(y) < 2L || length(unique(y)) < 2L) {
    return(NA_real_)
  }

  obj <- tryCatch(
    pROC::roc(
      response = y,
      predictor = p,
      levels = c(0, 1),
      direction = "<",
      quiet = TRUE
    ),
    error = function(e) NULL
  )

  if (is.null(obj)) NA_real_ else as.numeric(pROC::auc(obj))
}

safe_pr_auc <- function(y, p) {
  y <- as.integer(y)
  p <- as.numeric(p)
  keep <- is.finite(y) & is.finite(p)
  y <- y[keep]
  p <- p[keep]

  if (length(y) < 2L || length(unique(y)) < 2L) {
    return(NA_real_)
  }

  obj <- tryCatch(
    PRROC::pr.curve(
      scores.class0 = p[y == 1L],
      scores.class1 = p[y == 0L],
      curve = FALSE
    ),
    error = function(e) NULL
  )

  if (is.null(obj)) NA_real_ else as.numeric(obj$auc.integral)
}

probability_metrics <- function(y, p) {
  y <- as.integer(y)
  p <- as.numeric(p)
  keep <- is.finite(y) & is.finite(p)
  y <- y[keep]
  p <- p[keep]

  if (length(y) == 0L) {
    return(
      data.table(
        n_subjects = 0L,
        n_cases = 0L,
        n_controls = 0L,
        prevalence = NA_real_,
        AUROC = NA_real_,
        PR_AUC = NA_real_,
        PR_AUC_lift = NA_real_,
        Brier = NA_real_,
        log_loss = NA_real_,
        calibration_intercept = NA_real_,
        calibration_slope = NA_real_
      )
    )
  }

  p_clip <- pmin(pmax(p, 1e-8), 1 - 1e-8)
  lp <- qlogis(p_clip)
  calibration_intercept <- NA_real_
  calibration_slope <- NA_real_

  if (
    length(unique(y)) >= 2L &&
      is.finite(stats::sd(lp)) &&
      stats::sd(lp) > 0
  ) {
    intercept_fit <- tryCatch(
      suppressWarnings(
        stats::glm(
          y ~ 1 + offset(lp),
          family = stats::binomial()
        )
      ),
      error = function(e) NULL
    )

    slope_fit <- tryCatch(
      suppressWarnings(
        stats::glm(
          y ~ lp,
          family = stats::binomial()
        )
      ),
      error = function(e) NULL
    )

    if (!is.null(intercept_fit)) {
      calibration_intercept <- unname(coef(intercept_fit)[1L])
    }

    if (!is.null(slope_fit) && length(coef(slope_fit)) >= 2L) {
      calibration_slope <- unname(coef(slope_fit)[2L])
    }
  }

  prevalence <- mean(y)
  pr_auc <- safe_pr_auc(y, p)

  data.table(
    n_subjects = length(y),
    n_cases = sum(y == 1L),
    n_controls = sum(y == 0L),
    prevalence = prevalence,
    AUROC = safe_roc_auc(y, p),
    PR_AUC = pr_auc,
    PR_AUC_lift = pr_auc - prevalence,
    Brier = mean((p - y)^2),
    log_loss = -mean(
      y * log(p_clip) + (1 - y) * log(1 - p_clip)
    ),
    calibration_intercept = calibration_intercept,
    calibration_slope = calibration_slope
  )
}

corrected_repeated_cv <- function(difference, test_train_ratio) {
  d <- as.numeric(difference)
  ratio <- as.numeric(test_train_ratio)
  keep <- is.finite(d) & is.finite(ratio)
  d <- d[keep]
  ratio <- ratio[keep]
  n <- length(d)

  if (n < 3L) {
    return(
      data.table(
        n_splits = n,
        mean_difference = if (n > 0L) mean(d) else NA_real_,
        median_difference = if (n > 0L) median(d) else NA_real_,
        corrected_SE = NA_real_,
        corrected_CI_low = NA_real_,
        corrected_CI_high = NA_real_,
        corrected_t = NA_real_,
        corrected_df = if (n > 0L) n - 1L else NA_integer_,
        corrected_pvalue = NA_real_,
        mean_test_train_ratio = if (n > 0L) mean(ratio) else NA_real_
      )
    )
  }

  mean_d <- mean(d)
  variance_d <- stats::var(d)
  ratio_mean <- mean(ratio)
  corrected_se <- sqrt((1 / n + ratio_mean) * variance_d)
  df <- n - 1L

  if (!is.finite(corrected_se) || corrected_se == 0) {
    t_value <- NA_real_
    p_value <- NA_real_
    ci_low <- mean_d
    ci_high <- mean_d
  } else {
    t_value <- mean_d / corrected_se
    p_value <- 2 * stats::pt(-abs(t_value), df = df)
    critical <- stats::qt(0.975, df = df)
    ci_low <- mean_d - critical * corrected_se
    ci_high <- mean_d + critical * corrected_se
  }

  data.table(
    n_splits = n,
    mean_difference = mean_d,
    median_difference = median(d),
    corrected_SE = corrected_se,
    corrected_CI_low = ci_low,
    corrected_CI_high = ci_high,
    corrected_t = t_value,
    corrected_df = df,
    corrected_pvalue = p_value,
    mean_test_train_ratio = ratio_mean
  )
}

format_number <- function(x, digits = 3L) {
  ifelse(
    is.finite(x),
    formatC(x, digits = digits, format = "f"),
    "NA"
  )
}

format_pvalue <- function(x) {
  ifelse(
    !is.finite(x),
    "NA",
    ifelse(x < 0.001, "<0.001", formatC(x, digits = 3, format = "f"))
  )
}

save_plot <- function(plot_object, filename_stub, width, height) {
  ggsave(
    filename = file.path(figure_dir, paste0(filename_stub, ".pdf")),
    plot = plot_object,
    width = width,
    height = height,
    units = "in"
  )

  ggsave(
    filename = file.path(figure_dir, paste0(filename_stub, ".png")),
    plot = plot_object,
    width = width,
    height = height,
    units = "in",
    dpi = 400
  )
}

# ------------------------------- input loading -------------------------------

performance_list <- list()
prediction_list <- list()
coefficient_list <- list()
split_qc_list <- list()

for (i in seq_len(nrow(method_config))) {
  cfg <- method_config[i]
  collected_dir <- file.path(cfg$input_root, "collected")

  performance_file <- file.path(
    collected_dir,
    paste0(cfg$file_prefix, "_primary_performance_all_splits.tsv")
  )

  prediction_file <- file.path(
    collected_dir,
    paste0(cfg$file_prefix, "_primary_predictions_all_splits.tsv")
  )

  coefficient_file <- file.path(
    collected_dir,
    paste0(cfg$file_prefix, "_primary_coefficients_all_splits.tsv")
  )

  split_qc_file <- file.path(
    collected_dir,
    paste0(cfg$file_prefix, "_primary_split_qc_all_splits.tsv")
  )

  perf <- read_required_table(
    performance_file,
    paste0(cfg$method_display, " performance table")
  )

  pred <- read_required_table(
    prediction_file,
    paste0(cfg$method_display, " prediction table")
  )

  coef_dt <- read_required_table(
    coefficient_file,
    paste0(cfg$method_display, " coefficient table")
  )

  split_qc <- read_required_table(
    split_qc_file,
    paste0(cfg$method_display, " split-QC table")
  )

  require_columns(
    perf,
    c(
      "splitID", "model", "n_train", "n_test",
      "AUROC_test", "PR_AUC_test", "PR_AUC_lift_test", "Brier_test",
      "log_loss_test", "calibration_intercept_test",
      "calibration_slope_test", "sensitivity_test",
      "specificity_test", "balanced_accuracy_test",
      "n_DMR_selected_input", "n_DMR_usable",
      "n_methylation_features_input",
      "n_methylation_features_nonzero",
      "n_features_nonzero",
      "model_fallback"
    ),
    paste0(cfg$method_display, " performance table")
  )

  require_columns(
    pred,
    c(
      "splitID", "model", "ID", "FID", "AA_only",
      "prediction_set", "pred_prob"
    ),
    paste0(cfg$method_display, " prediction table")
  )

  require_columns(
    coef_dt,
    c(
      "splitID", "model", "feature", "feature_type",
      "coefficient", "selected_nonzero"
    ),
    paste0(cfg$method_display, " coefficient table")
  )

  require_columns(
    split_qc,
    c("splitID", "n_train", "n_test"),
    paste0(cfg$method_display, " split-QC table")
  )

  perf[, `:=`(
    source_method = cfg$method_key,
    method_display = cfg$method_display,
    primary_model_expected = cfg$primary_model,
    splitID = as.integer(splitID),
    model_fallback = as_logical_safe(model_fallback)
  )]

  pred[, `:=`(
    source_method = cfg$method_key,
    method_display = cfg$method_display,
    primary_model_expected = cfg$primary_model,
    splitID = as.integer(splitID),
    ID = as.character(ID),
    FID = as.character(FID),
    AA_only = as.integer(AA_only),
    pred_prob = as.numeric(pred_prob)
  )]

  coef_dt[, `:=`(
    source_method = cfg$method_key,
    method_display = cfg$method_display,
    primary_model_expected = cfg$primary_model,
    splitID = as.integer(splitID),
    selected_nonzero = as.integer(selected_nonzero)
  )]

  split_qc[, `:=`(
    source_method = cfg$method_key,
    method_display = cfg$method_display,
    splitID = as.integer(splitID)
  )]

  primary_count <- perf[model == cfg$primary_model, uniqueN(splitID)]
  baseline_count <- perf[model == "Covariate_only", uniqueN(splitID)]

  if (primary_count != expected_splits) {
    stop(
      cfg$method_display,
      " has ", primary_count,
      " primary-model splits; expected ", expected_splits, "."
    )
  }

  if (baseline_count != expected_splits) {
    stop(
      cfg$method_display,
      " has ", baseline_count,
      " covariate-only splits; expected ", expected_splits, "."
    )
  }

  performance_list[[cfg$method_key]] <- perf
  prediction_list[[cfg$method_key]] <- pred
  coefficient_list[[cfg$method_key]] <- coef_dt
  split_qc_list[[cfg$method_key]] <- split_qc

  cat(
    "Loaded ", cfg$method_display,
    ": performance rows=", nrow(perf),
    ", prediction rows=", nrow(pred),
    ", coefficient rows=", nrow(coef_dt),
    "\n",
    sep = ""
  )
}

performance_all <- rbindlist(
  performance_list,
  use.names = TRUE,
  fill = TRUE
)

prediction_all <- rbindlist(
  prediction_list,
  use.names = TRUE,
  fill = TRUE
)

coefficient_all <- rbindlist(
  coefficient_list,
  use.names = TRUE,
  fill = TRUE
)

split_qc_all <- rbindlist(
  split_qc_list,
  use.names = TRUE,
  fill = TRUE
)

# Derived calibration-error metrics are easier to compare because lower is
# unambiguously better.
performance_all[, calibration_intercept_abs_test := abs(
  calibration_intercept_test
)]
performance_all[, calibration_slope_error_test := abs(
  calibration_slope_test - 1
)]

primary_performance <- performance_all[
  model == primary_model_expected
]

baseline_performance_all <- performance_all[
  model == "Covariate_only"
]

setorder(primary_performance, source_method, splitID)
setorder(baseline_performance_all, source_method, splitID)

# ------------------------- baseline consistency checks -----------------------

baseline_metrics_for_qc <- c(
  "AUROC_test",
  "PR_AUC_test",
  "Brier_test",
  "log_loss_test",
  "calibration_intercept_test",
  "calibration_slope_test",
  "sensitivity_test",
  "specificity_test",
  "balanced_accuracy_test"
)

baseline_metric_qc <- rbindlist(
  lapply(
    baseline_metrics_for_qc,
    function(metric) {
      baseline_performance_all[
        ,
        {
          z <- as.numeric(get(metric))
          z <- z[is.finite(z)]

          list(
            n_methods = .N,
            minimum = if (length(z)) min(z) else NA_real_,
            maximum = if (length(z)) max(z) else NA_real_,
            range = if (length(z)) max(z) - min(z) else NA_real_
          )
        },
        by = splitID
      ][
        ,
        .(
          metric = metric,
          n_splits_checked = .N,
          maximum_cross_method_range = max(range, na.rm = TRUE),
          mean_cross_method_range = mean(range, na.rm = TRUE)
        )
      ]
    }
  ),
  use.names = TRUE,
  fill = TRUE
)

fwrite(
  baseline_metric_qc,
  file.path(qc_dir, "QC_covariate_performance_consistency.tsv"),
  sep = "\t",
  quote = FALSE,
  na = "NA"
)

baseline_prediction_qc_list <- list()
reference_baseline_prediction <- prediction_all[
  source_method == "MGCV" &
    model == "Covariate_only" &
    prediction_set == "test",
  .(
    splitID,
    ID,
    FID,
    AA_only_reference = AA_only,
    pred_prob_reference = pred_prob
  )
]

if (nrow(reference_baseline_prediction) == 0L) {
  stop("MGCV covariate-only test predictions are unavailable.")
}

for (method_key in method_config$method_key) {
  current_method_key <- method_key

  candidate <- prediction_all[
    source_method == method_key &
      model == "Covariate_only" &
      prediction_set == "test",
    .(
      splitID,
      ID,
      FID,
      AA_only_candidate = AA_only,
      pred_prob_candidate = pred_prob
    )
  ]

  merged_baseline <- merge(
    reference_baseline_prediction,
    candidate,
    by = c("splitID", "ID", "FID"),
    all = TRUE
  )

  baseline_prediction_qc_list[[method_key]] <- data.table(
    source_method = method_key,
    method_display = method_config[
      method_key == current_method_key,
      method_display
    ][1L],
    n_reference_rows = nrow(reference_baseline_prediction),
    n_candidate_rows = nrow(candidate),
    n_matched_rows = merged_baseline[
      !is.na(pred_prob_reference) & !is.na(pred_prob_candidate),
      .N
    ],
    n_outcome_mismatches = merged_baseline[
      !is.na(AA_only_reference) &
        !is.na(AA_only_candidate) &
        AA_only_reference != AA_only_candidate,
      .N
    ],
    mean_abs_prediction_difference = merged_baseline[
      ,
      mean(
        abs(pred_prob_reference - pred_prob_candidate),
        na.rm = TRUE
      )
    ],
    max_abs_prediction_difference = merged_baseline[
      ,
      max(
        abs(pred_prob_reference - pred_prob_candidate),
        na.rm = TRUE
      )
    ]
  )
}

baseline_prediction_qc <- rbindlist(
  baseline_prediction_qc_list,
  use.names = TRUE,
  fill = TRUE
)

fwrite(
  baseline_prediction_qc,
  file.path(qc_dir, "QC_covariate_prediction_consistency.tsv"),
  sep = "\t",
  quote = FALSE,
  na = "NA"
)

max_baseline_prediction_difference <- max(
  baseline_prediction_qc$max_abs_prediction_difference,
  na.rm = TRUE
)

if (
  is.finite(max_baseline_prediction_difference) &&
    max_baseline_prediction_difference > 1e-8
) {
  warning(
    "Covariate-only predictions differ across method pipelines. ",
    "See QC_covariate_prediction_consistency.tsv. Maximum difference: ",
    signif(max_baseline_prediction_difference, 6)
  )
}

# Use the MGCV covariate-only result once in cross-method descriptive tables.
baseline_reference_performance <- baseline_performance_all[
  source_method == "MGCV"
]
baseline_reference_performance[, method_display := "Covariates only"]
baseline_reference_performance[, source_method := "Covariate_only"]

performance_for_summary <- rbindlist(
  list(primary_performance, baseline_reference_performance),
  use.names = TRUE,
  fill = TRUE
)

performance_for_summary[, method_display := factor(
  method_display,
  levels = method_levels
)]

# Save standardized combined analysis datasets.
fwrite(
  primary_performance,
  file.path(data_dir, "primary_performance_4_methods_all_splits.tsv"),
  sep = "\t",
  quote = FALSE,
  na = "NA"
)

