# -------------------- corrected pairwise method comparison -------------------

comparison_metric_dictionary <- data.table(
  metric = c(
    "AUROC_test",
    "PR_AUC_test",
    "Brier_test",
    "log_loss_test",
    "calibration_intercept_abs_test",
    "calibration_slope_error_test",
    "balanced_accuracy_test"
  ),
  metric_display = c(
    "AUROC",
    "PR-AUC",
    "Brier score",
    "Log loss",
    "Absolute calibration intercept",
    "Absolute calibration-slope error",
    "Balanced accuracy"
  ),
  lower_is_better = c(FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE),
  main_manuscript_metric = c(TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE)
)

method_pairs <- combn(
  method_config$method_key,
  2L,
  simplify = FALSE
)

pairwise_results_list <- list()
pairwise_split_differences_list <- list()
result_index <- 0L
split_index <- 0L

for (pair in method_pairs) {
  method_a <- pair[1L]
  method_b <- pair[2L]

  display_a <- method_config[method_key == method_a, method_display][1L]
  display_b <- method_config[method_key == method_b, method_display][1L]

  perf_a <- primary_performance[
    source_method == method_a
  ]
  perf_b <- primary_performance[
    source_method == method_b
  ]

  paired <- merge(
    perf_a,
    perf_b,
    by = "splitID",
    suffixes = c("_A", "_B"),
    all = FALSE
  )

  if (nrow(paired) != expected_splits) {
    stop(
      "Pair ", display_a, " versus ", display_b,
      " has ", nrow(paired), " matched splits; expected ",
      expected_splits, "."
    )
  }

  paired[, test_train_ratio := (
    n_test_A / n_train_A + n_test_B / n_train_B
  ) / 2]

  for (m in seq_len(nrow(comparison_metric_dictionary))) {
    metric <- comparison_metric_dictionary$metric[m]
    metric_display <- comparison_metric_dictionary$metric_display[m]
    lower_is_better <- comparison_metric_dictionary$lower_is_better[m]

    raw_difference <- paired[[paste0(metric, "_A")]] -
      paired[[paste0(metric, "_B")]]

    favorable_sign <- if (lower_is_better) -1 else 1
    favorable_difference <- favorable_sign * raw_difference

    corrected <- corrected_repeated_cv(
      raw_difference,
      paired$test_train_ratio
    )

    corrected[, `:=`(
      method_A = method_a,
      method_B = method_b,
      method_A_display = display_a,
      method_B_display = display_b,
      comparison = paste0(display_a, " minus ", display_b),
      metric = metric,
      metric_display = metric_display,
      lower_is_better = lower_is_better,
      favorable_sign = favorable_sign,
      favorable_mean_difference = favorable_sign * mean_difference,
      favorable_CI_low = if (favorable_sign == 1) {
        corrected_CI_low
      } else {
        -corrected_CI_high
      },
      favorable_CI_high = if (favorable_sign == 1) {
        corrected_CI_high
      } else {
        -corrected_CI_low
      },
      win_rate_method_A = mean(
        favorable_difference > 0,
        na.rm = TRUE
      ),
      tie_rate = mean(
        favorable_difference == 0,
        na.rm = TRUE
      )
    )]

    result_index <- result_index + 1L
    pairwise_results_list[[result_index]] <- corrected

    split_index <- split_index + 1L
    pairwise_split_differences_list[[split_index]] <- data.table(
      splitID = paired$splitID,
      method_A = method_a,
      method_B = method_b,
      method_A_display = display_a,
      method_B_display = display_b,
      metric = metric,
      metric_display = metric_display,
      raw_difference_A_minus_B = raw_difference,
      favorable_difference_for_A = favorable_difference,
      test_train_ratio = paired$test_train_ratio
    )
  }
}

pairwise_results <- rbindlist(
  pairwise_results_list,
  use.names = TRUE,
  fill = TRUE
)

pairwise_results[
  ,
  p_holm_all_pairs := p.adjust(
    corrected_pvalue,
    method = "holm"
  ),
