# ---------------------- each method versus covariates ------------------------

method_vs_baseline_results_list <- list()
method_vs_baseline_split_list <- list()
result_index <- 0L
split_index <- 0L

for (method_key in method_config$method_key) {
  current_method_key <- method_key

  display_method <- method_config[
    method_key == current_method_key,
    method_display
  ][1L]

  method_perf <- primary_performance[source_method == method_key]
  baseline_perf <- baseline_performance_all[source_method == method_key]

  paired <- merge(
    method_perf,
    baseline_perf,
    by = "splitID",
    suffixes = c("_Method", "_Baseline"),
    all = FALSE
  )

  if (nrow(paired) != expected_splits) {
    stop(
      display_method,
      " versus covariates has ", nrow(paired),
      " matched splits; expected ", expected_splits, "."
    )
  }

  paired[, test_train_ratio := n_test_Method / n_train_Method]

  for (m in seq_len(nrow(comparison_metric_dictionary))) {
    metric <- comparison_metric_dictionary$metric[m]
    metric_display <- comparison_metric_dictionary$metric_display[m]
    lower_is_better <- comparison_metric_dictionary$lower_is_better[m]

    raw_difference <- paired[[paste0(metric, "_Method")]] -
      paired[[paste0(metric, "_Baseline")]]

    favorable_sign <- if (lower_is_better) -1 else 1
    improvement <- favorable_sign * raw_difference

    corrected <- corrected_repeated_cv(
      raw_difference,
      paired$test_train_ratio
    )

    corrected[, `:=`(
      source_method = method_key,
      method_display = display_method,
      comparison = paste0(display_method, " minus Covariates only"),
      metric = metric,
      metric_display = metric_display,
      lower_is_better = lower_is_better,
      favorable_sign = favorable_sign,
      favorable_mean_improvement = favorable_sign * mean_difference,
      favorable_CI_low = if (favorable_sign == 1) {
        corrected_CI_low
      } else {
        -corrected_CI_high
      },
      favorable_CI_high = if (favorable_sign == 1) {
        corrected_CI_high
      } else {
        -corrected_CI_low
      },
      improvement_win_rate = mean(improvement > 0, na.rm = TRUE),
      tie_rate = mean(improvement == 0, na.rm = TRUE)
    )]

    result_index <- result_index + 1L
    method_vs_baseline_results_list[[result_index]] <- corrected

    split_index <- split_index + 1L
    method_vs_baseline_split_list[[split_index]] <- data.table(
      splitID = paired$splitID,
      source_method = method_key,
      method_display = display_method,
      metric = metric,
      metric_display = metric_display,
      raw_difference_method_minus_baseline = raw_difference,
      favorable_improvement = improvement,
      test_train_ratio = paired$test_train_ratio
    )
  }
}

