# ------------------------- ROC and PR curve coordinates ----------------------

roc_coordinates_list <- list()
pr_coordinates_list <- list()

for (method_name in method_levels) {
  dd <- subject_average[
    as.character(method_display) == method_name
  ]

  if (nrow(dd) == 0L || uniqueN(dd$AA_only) < 2L) next

  roc_obj <- pROC::roc(
    dd$AA_only,
    dd$mean_pred_prob,
    levels = c(0, 1),
    direction = "<",
    quiet = TRUE
  )

  roc_coordinates_list[[method_name]] <- data.table(
    method_display = method_name,
    FPR = 1 - roc_obj$specificities,
    TPR = roc_obj$sensitivities,
    AUROC = as.numeric(pROC::auc(roc_obj))
  )

  pr_obj <- PRROC::pr.curve(
    scores.class0 = dd[AA_only == 1L, mean_pred_prob],
    scores.class1 = dd[AA_only == 0L, mean_pred_prob],
    curve = TRUE
  )

  pr_coordinates_list[[method_name]] <- data.table(
    method_display = method_name,
    Recall = pr_obj$curve[, 1L],
    Precision = pr_obj$curve[, 2L],
    PR_AUC = as.numeric(pr_obj$auc.integral),
    prevalence = mean(dd$AA_only)
  )
}

roc_coordinates <- rbindlist(
  roc_coordinates_list,
  use.names = TRUE,
  fill = TRUE
)

pr_coordinates <- rbindlist(
  pr_coordinates_list,
  use.names = TRUE,
  fill = TRUE
)

fwrite(
  roc_coordinates,
  file.path(data_dir, "subject_average_ROC_coordinates.tsv"),
  sep = "\t",
  quote = FALSE,
  na = "NA"
)

fwrite(
  pr_coordinates,
  file.path(data_dir, "subject_average_PR_coordinates.tsv"),
  sep = "\t",
  quote = FALSE,
  na = "NA"
)

# ---------------------------- calibration bins -------------------------------

calibration_bins <- subject_average[
  ,
  {
    n_local <- .N
    rank_local <- frank(
      mean_pred_prob,
      ties.method = "average",
      na.last = "keep"
    )

    bin_local <- pmin(
      n_calibration_bins,
      pmax(
        1L,
        ceiling(rank_local / n_local * n_calibration_bins)
      )
    )

    .(
      calibration_bin = bin_local,
      AA_only = AA_only,
      mean_pred_prob = mean_pred_prob
    )
  },
  by = .(
    source_method,
    method_display
  )
][
  ,
  .(
    n = .N,
    mean_predicted = mean(mean_pred_prob, na.rm = TRUE),
    observed = mean(AA_only, na.rm = TRUE),
    observed_SE = sqrt(
      mean(AA_only, na.rm = TRUE) *
        (1 - mean(AA_only, na.rm = TRUE)) /
        .N
    )
  ),
  by = .(
    source_method,
    method_display,
    calibration_bin
  )
]

calibration_bins[, `:=`(
  observed_CI_low = pmax(0, observed - 1.96 * observed_SE),
  observed_CI_high = pmin(1, observed + 1.96 * observed_SE)
)]

fwrite(
  calibration_bins,
  file.path(data_dir, "subject_average_calibration_bins.tsv"),
  sep = "\t",
  quote = FALSE,
  na = "NA"
)

# ---------------------- region/feature selection stability -------------------

primary_coefficients <- coefficient_all[
  model == primary_model_expected &
    feature_type == "methylation" &
    grepl("^DMRpc[0-9]+_", feature)
]

primary_coefficients[, region_key := sub(
  "^DMRpc[0-9]+_",
  "",
  feature
)]

# DMRcate and BSmooth identifiers end in an artificial within-split index.
# Remove it so exact genomic intervals can be compared across splits.
primary_coefficients[
  source_method %in% c("DMRcate", "BSmooth"),
  region_key := sub("_[0-9]{5}$", "", region_key)
]

region_split_selection <- primary_coefficients[
  ,
  .(
    region_available = 1L,
    region_selected = as.integer(any(selected_nonzero == 1L)),
    n_PC_features_available = .N,
    n_PC_features_selected = sum(selected_nonzero == 1L, na.rm = TRUE),
    maximum_abs_coefficient = max(abs(coefficient), na.rm = TRUE)
  ),
  by = .(
    source_method,
    method_display,
    splitID,
    region_key
  )
]

region_stability <- region_split_selection[
  ,
  .(
    n_splits_available = uniqueN(splitID),
    n_splits_selected = sum(region_selected),
    overall_selection_rate = sum(region_selected) / expected_splits,
    conditional_selection_rate = sum(region_selected) / uniqueN(splitID),
    mean_selected_PC_count = mean(n_PC_features_selected),
    mean_maximum_abs_coefficient = mean(
      maximum_abs_coefficient,
      na.rm = TRUE
    )
  ),
  by = .(
    source_method,
    method_display,
    region_key
  )
]

setorder(
  region_stability,
  source_method,
  -n_splits_selected,
  -n_splits_available,
  region_key
)

