# ----------------------- manuscript text and captions ------------------------

mean_metric_table <- performance_summary_numeric[
  metric %in% c("AUROC_test", "PR_AUC_test", "Brier_test") &
    as.character(method_display) != "Covariates only",
  .(
    method_display = as.character(method_display),
    metric,
    mean,
    SD,
    median,
    Q1,
    Q3
  )
]

best_auc <- mean_metric_table[
  metric == "AUROC_test"
][order(-mean)][1L]

best_pr <- mean_metric_table[
  metric == "PR_AUC_test"
][order(-mean)][1L]

best_brier <- mean_metric_table[
  metric == "Brier_test"
][order(mean)][1L]

results_text <- c(
  "PRIMARY REGIONAL-METHOD PREDICTION COMPARISON",
  "",
  paste0(
    "Across ", expected_splits,
    " repeated family-aware outer train/test splits, the highest mean test AUROC was observed for ",
    best_auc$method_display,
    " (mean ", format_number(best_auc$mean, 3L),
    ", SD ", format_number(best_auc$SD, 3L), ")."
  ),
  paste0(
    "The highest mean test PR-AUC was observed for ",
    best_pr$method_display,
    " (mean ", format_number(best_pr$mean, 3L),
    ", SD ", format_number(best_pr$SD, 3L), ")."
  ),
  paste0(
    "The lowest mean Brier score was observed for ",
    best_brier$method_display,
    " (mean ", format_number(best_brier$mean, 3L),
    ", SD ", format_number(best_brier$SD, 3L), ")."
  ),
  "",
  "GAM-DMR VERSUS ALTERNATIVE REGIONAL METHODS",
  ""
)

for (metric_name in c("AUROC", "PR-AUC", "Brier score")) {
  dd <- gam_vs_alternatives[metric_display == metric_name]

  for (i in seq_len(nrow(dd))) {
    direction_text <- if (dd$favorable_mean_difference[i] > 0) {
      "favored GAM-DMR"
    } else if (dd$favorable_mean_difference[i] < 0) {
      paste0("favored ", dd$method_B_display[i])
    } else {
      "showed no average difference"
    }

    results_text <- c(
      results_text,
      paste0(
        metric_name,
        ": GAM-DMR versus ", dd$method_B_display[i],
        " had a favorable-direction mean difference of ",
        format_number(dd$favorable_mean_difference[i], 3L),
        " (corrected 95% CI ",
        format_number(dd$favorable_CI_low[i], 3L),
        " to ",
        format_number(dd$favorable_CI_high[i], 3L),
        "; Holm-adjusted p ",
        format_pvalue(dd$p_holm_GAM_DMR_vs_alternatives[i]),
        "), which ", direction_text, "."
      )
    )
  }

  results_text <- c(results_text, "")
}

results_text <- c(
  results_text,
  "Interpretation note: for AUROC and PR-AUC, positive favorable-direction differences mean higher performance for GAM-DMR. For Brier score, positive favorable-direction differences mean a lower Brier score for GAM-DMR.",
  "Corrected repeated-CV confidence intervals account approximately for overlap among the repeated 80/20 splits. The subject-averaged ROC, PR, and calibration analyses are secondary descriptive ensemble summaries.",
  ""
)

writeLines(
  results_text,
  con = file.path(output_root, "manuscript_results_summary.txt")
)

caption_text <- c(
  "Figure 1. Predictive performance across repeated family-aware outer test splits. Violin and box plots show the distributions of test-set AUROC, PR-AUC, and Brier score across the repeated splits. White diamonds indicate arithmetic means. All regional models used split-specific training-derived DMRs, training-only PC construction, family-grouped inner cross-validation, and an outer held-out family test set.",
  "",
  "Figure 2. Incremental predictive performance beyond clinical covariates. Values represent the paired split-specific improvement of each regional methylation model over the covariate-only model. Positive values indicate improvement; Brier-score differences were sign-reversed so that positive values consistently indicate better performance.",
  "",
  "Figure 3. Paired comparison of GAM-DMR with alternative regional methods. Points show corrected repeated-CV mean differences and horizontal bars show corrected 95% confidence intervals. Effects are oriented so that positive values favor GAM-DMR; Brier-score differences were sign-reversed.",
  "",
  "Figure 4A. Subject-averaged out-of-fold ROC curves. For each participant and method, predicted probabilities were averaged across all outer splits in which that participant was held out. This is a secondary descriptive ensemble analysis.",
  "",
  "Figure 4B. Subject-averaged out-of-fold precision-recall curves. The dashed horizontal line shows the observed AA prevalence. This is a secondary descriptive ensemble analysis.",
  "",
  "Figure 5. Calibration of subject-averaged out-of-fold predictions. Points show observed AA proportions within prediction-ranked bins; error bars show approximate 95% binomial confidence intervals. The dashed diagonal represents perfect calibration.",
  "",
  "Supplementary Figure 1. Regional feature-set complexity across outer splits, including selected DMR counts, usable DMR counts, and nonzero methylation PC features.",
  "",
  "Supplementary Figure 2. Relationship between the number of selected training-derived DMRs and held-out test performance.",
  "",
  "Supplementary Figure 3. Most frequently retained regional methylation predictors. A region is counted as retained when at least one PC feature from that region has a nonzero LASSO coefficient in an outer split."
)

writeLines(
  caption_text,
  con = file.path(output_root, "manuscript_figure_captions.txt")
